def resolve(path, cwd, links):
    if links is None:
        links = {}

    # Start with the initial path
    if path.startswith('/'):
        current = '/'
        components = path.split('/')[1:]
    else:
        current = cwd
        components = path.split('/')

    link_count = 0
    i = 0

    while i < len(components):
        component = components[i]

        # Skip empty components and '.'
        if component == '' or component == '.':
            i += 1
            continue

        # Handle '..'
        if component == '..':
            if current != '/':
                # Move to parent directory
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            i += 1
            continue

        # Append the component
        if current == '/':
            candidate = '/' + component
        else:
            candidate = current + '/' + component

        # Check if this path is a symlink
        if candidate in links:
            link_count += 1
            if link_count > 8:
                return None

            target = links[candidate]

            # Resolve the target
            if target.startswith('/'):
                current = '/'
                target_components = target.split('/')[1:]
            else:
                # Target is relative to the directory containing the link
                if candidate == '/':
                    current = '/'
                else:
                    current = candidate.rsplit('/', 1)[0]
                target_components = target.split('/')

            # Replace the remaining components with target components + remaining
            components = target_components + components[i+1:]
            i = 0
            continue

        # Not a symlink, just update current
        current = candidate
        i += 1

    # Result has no trailing slash, except '/' itself
    if current == '/':
        return '/'
    else:
        return current

